[tikz]
% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[],"reference":"compare-box-plots practice.mastery[1].solution_text; original box geometry and values retained; unshaded boxes; ordinary marks black"}
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.8]
\draw[{Stealth}-{Stealth}] (-0.4,0)--(6.40,0);
\draw (0,-0.08)--(0,0.08); \node[below,font=\scriptsize] at (0,-0.16) {$0$};
\draw (1,-0.08)--(1,0.08); \node[below,font=\scriptsize] at (1,-0.16) {$10$};
\draw (2,-0.08)--(2,0.08); \node[below,font=\scriptsize] at (2,-0.16) {$20$};
