\node[below,font=\scriptsize] at (3.00,-1.0) {Points scored};
\node[font=\small] at (3.00,3.85) {Volleyball points per set};
\draw[thick] (0.5,1.2)--(1.5,1.2);
\draw[thick] (3,1.2)--(3.8,1.2);
