\draw[thick] (3.8,2.7)--(4.5,2.7);
\draw[thick] (5.5,2.7)--(5.8,2.7);
\draw[thick] (3.8,2.5)--(3.8,2.9);
\draw[thick] (5.8,2.5)--(5.8,2.9);
\draw[thick,fill=none] (4.5,2.3) rectangle (5.5,3.1);
\draw[thick] (5,2.3)--(5,3.1);
